def link_existing(apps, schema_editor):
    """Accounts already using a licence of an organisation stay linked to it."""
    Activation = apps.get_model("licensing", "Activation")
    OrgLink = apps.get_model("licensing", "OrgLink")
    for act in Activation.objects.filter(license__customer__organisation__isnull=False).select_related(
            "license__customer"):
        OrgLink.objects.get_or_create(app_client_id=act.app_client_id, account_ref=act.account_ref,
                                      organisation_id=act.license.customer.organisation_id)


